import{_ as t,o as e,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"模型网关","description":"以 ADR 形式决定 Model Gateway 的位置、可替换性与故障隔离；实现外链 backend，路由策略外链 agent。","frontmatter":{"title":"模型网关","description":"以 ADR 形式决定 Model Gateway 的位置、可替换性与故障隔离；实现外链 backend，路由策略外链 agent。","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"ts-ai/architecture/design-decisions/model-gateway.md","filePath":"ts-ai/architecture/design-decisions/model-gateway.md","lastUpdated":1786166505000}'),d={name:"ts-ai/architecture/design-decisions/model-gateway.md"};function l(r,a,i,o,p,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="模型网关" tabindex="-1">模型网关 <a class="header-anchor" href="#模型网关" aria-label="Permalink to &quot;模型网关&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>售后与知识库服务里，若每个 Nest Service、每个 Agent 工厂各自 <code>new ChatOpenAI({ apiKey, model, timeout })</code>，会在密钥轮换、超时策略、供应商切换和故障隔离上同时失控。<strong>Model Gateway</strong> 把「如何拿到一个可用的 ChatModel」收成统一入口。本篇是架构 ADR：决定<strong>要不要网关、放哪、保证什么</strong>；不实现 Registry 代码。</p><p>实现见 <a href="/ts-ai/backend/ai-service/model-gateway">Model Gateway</a>。按任务选大小模型与 <code>withFallbacks</code> 策略见 <a href="/ts-ai/agent/models-output/model-routing-fallbacks">模型路由与回退</a>。分层位置见 <a href="/ts-ai/architecture/design-decisions/ts-ai-fullstack-architecture">TS-AI 全栈分层架构</a>。</p><h2 id="_1-背景" tabindex="-1">1. 背景 <a class="header-anchor" href="#_1-背景" aria-label="Permalink to &quot;1. 背景&quot;">​</a></h2><h3 id="_1-1-驱动场景" tabindex="-1">1.1 驱动场景 <a class="header-anchor" href="#_1-1-驱动场景" aria-label="Permalink to &quot;1.1 驱动场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>无网关时的痛点</th></tr></thead><tbody><tr><td>售后短问答</td><td>各处硬编码 <code>gpt-4o-mini</code>，无法统一超时</td></tr><tr><td>售后退款说明生成</td><td>与短问答抢同一 Key 配置副本，轮换漏改</td></tr><tr><td>知识库 Embedding + Chat</td><td>两套客户端构造逻辑分叉</td></tr><tr><td>供应商区域故障</td><td>业务代码里到处 try/catch 换模型</td></tr></tbody></table><h3 id="_1-2-决策问题" tabindex="-1">1.2 决策问题 <a class="header-anchor" href="#_1-2-决策问题" aria-label="Permalink to &quot;1.2 决策问题&quot;">​</a></h3><p>是否在 Nest 应用内引入 <strong>Model Gateway</strong> 作为唯一（或主）模型交付面？若引入，网关保证哪些不变量，哪些明确不负责？</p><h2 id="_2-约束与决策标准" tabindex="-1">2. 约束与决策标准 <a class="header-anchor" href="#_2-约束与决策标准" aria-label="Permalink to &quot;2. 约束与决策标准&quot;">​</a></h2><h3 id="_2-1-硬约束" tabindex="-1">2.1 硬约束 <a class="header-anchor" href="#_2-1-硬约束" aria-label="Permalink to &quot;2.1 硬约束&quot;">​</a></h3><table tabindex="0"><thead><tr><th>约束</th><th>说明</th></tr></thead><tbody><tr><td>密钥不进浏览器</td><td>Nuxt 不得持有供应商 Key</td></tr><tr><td>TypeScript 全栈</td><td>Nest 宿主；LangChain.js ChatModel 为交付物</td></tr><tr><td>多别名</td><td>至少 <code>default</code> / 快路径 / 推理路径（名称可调整）</td></tr><tr><td>可观测</td><td>能把 alias、供应商、错误关联到 Run / Trace</td></tr><tr><td>自托管优先</td><td>不强制绑定单一托管 Agent 平台才能换模型</td></tr></tbody></table><h3 id="_2-2-决策标准-权重示意" tabindex="-1">2.2 决策标准（权重示意） <a class="header-anchor" href="#_2-2-决策标准-权重示意" aria-label="Permalink to &quot;2.2 决策标准（权重示意）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>标准</th><th>权重</th><th style="text-align:right;">含义</th></tr></thead><tbody><tr><td>密钥与配置集中</td><td>25</td><td style="text-align:right;">一轮换即可全局生效</td></tr><tr><td>故障隔离</td><td>20</td><td style="text-align:right;">模型故障不拖垮无关模块启动</td></tr><tr><td>可替换供应商</td><td>20</td><td style="text-align:right;">改注册表而非改全部 Agent</td></tr><tr><td>与路由策略解耦</td><td>15</td><td style="text-align:right;">Gateway 交付 ≠ 内容路由</td></tr><tr><td>实现与认知成本</td><td>10</td><td style="text-align:right;">避免过度平台化</td></tr><tr><td>测试可注入</td><td>10</td><td style="text-align:right;">单测可替换 Fake ChatModel</td></tr></tbody></table><h3 id="_2-3-非目标-写进-adr-防膨胀" tabindex="-1">2.3 非目标（写进 ADR 防膨胀） <a class="header-anchor" href="#_2-3-非目标-写进-adr-防膨胀" aria-label="Permalink to &quot;2.3 非目标（写进 ADR 防膨胀）&quot;">​</a></h3><p>Gateway <strong>不是</strong>：</p><ul><li>Prompt 配置中心</li><li>Agent / Tool 注册表</li><li>按自然语言做意图分类的路由器（可调用路由链，但路由策略另文）</li><li>对外公网「模型代理 SaaS」</li></ul><p>把非目标写清，避免迭代中把 CMS、RBAC、计费全塞进 Registry。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-a-各处直接构造-chatmodel" tabindex="-1">3.1 A. 各处直接构造 ChatModel <a class="header-anchor" href="#_3-1-a-各处直接构造-chatmodel" aria-label="Permalink to &quot;3.1 A. 各处直接构造 ChatModel&quot;">​</a></h3><p>每个 Agent Module <code>new ChatOpenAI(...)</code>。</p><ul><li>优点：路径短、无额外抽象。</li><li>缺点：密钥与超时复制；替换成本线性上升；测试替身分散。</li></ul><h3 id="_3-2-b-nest-内-model-gateway-推荐默认" tabindex="-1">3.2 B. Nest 内 Model Gateway（推荐默认） <a class="header-anchor" href="#_3-2-b-nest-内-model-gateway-推荐默认" aria-label="Permalink to &quot;3.2 B. Nest 内 Model Gateway（推荐默认）&quot;">​</a></h3><p><code>ModelGateway.resolve(alias) → BaseChatModel</code>（或已包装的 Runnable）。Registry 集中读 <code>ConfigService</code>，缓存实例。</p><ul><li>优点：满足硬约束；与手册 backend 实现一致；Agent 只依赖别名。</li><li>缺点：多一层间接；别名治理需要约定。</li></ul><h3 id="_3-3-c-独立模型微服务" tabindex="-1">3.3 C. 独立模型微服务 <a class="header-anchor" href="#_3-3-c-独立模型微服务" aria-label="Permalink to &quot;3.3 C. 独立模型微服务&quot;">​</a></h3><p>单独进程暴露「补全 HTTP API」，Nest 再包一层。</p><ul><li>优点：语言异构、强隔离、可独立扩缩。</li><li>缺点：延迟与运维面上升；TS 全栈早期通常过重；流式与取消语义要重新设计。</li></ul><h3 id="_3-4-d-仅使用托管网关-供应商账号代理" tabindex="-1">3.4 D. 仅使用托管网关 / 供应商账号代理 <a class="header-anchor" href="#_3-4-d-仅使用托管网关-供应商账号代理" aria-label="Permalink to &quot;3.4 D. 仅使用托管网关 / 供应商账号代理&quot;">​</a></h3><p>完全依赖云厂商统一入口，应用内无 Registry。</p><ul><li>优点：少代码。</li><li>缺点：退出与多供应商策略受平台约束；仍可能缺「业务别名」层。</li></ul><h2 id="_4-对比" tabindex="-1">4. 对比 <a class="header-anchor" href="#_4-对比" aria-label="Permalink to &quot;4. 对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>标准</th><th>A 直接构造</th><th>B 应用内 Gateway</th><th>C 模型微服务</th><th>D 纯托管入口</th></tr></thead><tbody><tr><td>密钥集中</td><td>差</td><td>好</td><td>好</td><td>中（在平台）</td></tr><tr><td>故障隔离</td><td>差（构造散落）</td><td>中–好（模块边界）</td><td>好（进程）</td><td>中</td></tr><tr><td>可替换</td><td>差</td><td>好</td><td>好</td><td>差–中</td></tr><tr><td>与路由解耦</td><td>差（易写 if）</td><td>好（约定别名）</td><td>好</td><td>视平台</td></tr><tr><td>成本</td><td>低</td><td>低–中</td><td>高</td><td>低–中</td></tr><tr><td>测试注入</td><td>差</td><td>好</td><td>中</td><td>差</td></tr></tbody></table><p><strong>售后/知识库默认全栈</strong>下，B 在加权上通常优于 A；C 留给多语言或极大调用量；D 可作传输层，但不取代业务别名。</p><h2 id="_5-决策" tabindex="-1">5. 决策 <a class="header-anchor" href="#_5-决策" aria-label="Permalink to &quot;5. 决策&quot;">​</a></h2><h3 id="_5-1-选择" tabindex="-1">5.1 选择 <a class="header-anchor" href="#_5-1-选择" aria-label="Permalink to &quot;5.1 选择&quot;">​</a></h3><p><strong>采用候选 B：在 Nest 应用内实现 Model Gateway</strong>，作为基础设施层组件。</p><p>配套约定：</p><ol><li>业务与 Agent 工厂<strong>只</strong>通过 <code>resolve(alias)</code> 取模型。</li><li>别名是稳定契约（如 <code>support-fast</code>、<code>support-reasoning</code>、<code>kb-embed</code>），具体 model id 可配置替换。</li><li><strong>内容级路由</strong>（这句话用大模型还是小模型）写在路由/回退策略中，不在 Gateway 内解析用户自然语言。</li><li>Gateway <strong>可以</strong>在注册期组装 <code>withFallbacks</code>，但策略文档归属 agent 路由篇与本 ADR 的「批准的链」。</li></ol><h3 id="_5-2-明确不选择" tabindex="-1">5.2 明确不选择 <a class="header-anchor" href="#_5-2-明确不选择" aria-label="Permalink to &quot;5.2 明确不选择&quot;">​</a></h3><table tabindex="0"><thead><tr><th>未选</th><th>原因</th></tr></thead><tbody><tr><td>A</td><td>违反密钥集中与可替换标准</td></tr><tr><td>C</td><td>当前约束下 TCO 过高；复查条件见 §7</td></tr><tr><td>仅 D</td><td>缺少业务别名与本地 Fake 注入面</td></tr></tbody></table><h2 id="_6-后果与适用边界" tabindex="-1">6. 后果与适用边界 <a class="header-anchor" href="#_6-后果与适用边界" aria-label="Permalink to &quot;6. 后果与适用边界&quot;">​</a></h2><h3 id="_6-1-位置-架构后果" tabindex="-1">6.1 位置（架构后果） <a class="header-anchor" href="#_6-1-位置-架构后果" aria-label="Permalink to &quot;6.1 位置（架构后果）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Controller / UseCase</span></span>
<span class="line"><span>  → AgentFactory / Graph node factory</span></span>
<span class="line"><span>      → ModelGateway.resolve(alias)</span></span>
<span class="line"><span>          → ModelRegistry（密钥、timeout、可选 fallbacks）</span></span>
<span class="line"><span>              → ChatOpenAI / 其他 ChatModel</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li><strong>位置</strong>：Nest 进程内、基础设施层；不是独立公网产品 API（除非另立 ADR）。</li><li><strong>可见性</strong>：仅服务端模块注入；不导出给 Nuxt。</li></ul><h3 id="_6-2-可替换性" tabindex="-1">6.2 可替换性 <a class="header-anchor" href="#_6-2-可替换性" aria-label="Permalink to &quot;6.2 可替换性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>替换对象</th><th>期望改动面</th></tr></thead><tbody><tr><td>同供应商换 model id</td><td>配置 / Registry</td></tr><tr><td>换备用供应商</td><td>Registry + 密钥；别名保持</td></tr><tr><td>换 ChatModel 实现类</td><td>Registry 工厂；Agent 代码不改</td></tr><tr><td>换别名语义</td><td>需版本化别名或迁移说明（破坏性）</td></tr></tbody></table><h3 id="_6-3-故障隔离" tabindex="-1">6.3 故障隔离 <a class="header-anchor" href="#_6-3-故障隔离" aria-label="Permalink to &quot;6.3 故障隔离&quot;">​</a></h3><table tabindex="0"><thead><tr><th>故障</th><th>期望行为</th></tr></thead><tbody><tr><td>某别名上游 429/5xx</td><td>该次 Run 失败或走已注册 fallbacks；其它别名可用</td></tr><tr><td>启动时缺 Key</td><td>快速失败并明确日志；避免半开服务静默</td></tr><tr><td>Registry 构造抛错</td><td>限制在 AI Module 启动；不与无关 HTTP 模块循环依赖</td></tr><tr><td>慢模型拖垮事件循环</td><td>超时在模型客户端；Run 级 deadline 在应用层</td></tr></tbody></table><p>隔离<strong>不是</strong>「一个模型挂了整个 Nest 进程必须活得像没事」——进程级 OOM 仍可能发生；而是避免配置与重试逻辑蜘蛛网化。</p><h3 id="_6-4-适用与不适用" tabindex="-1">6.4 适用与不适用 <a class="header-anchor" href="#_6-4-适用与不适用" aria-label="Permalink to &quot;6.4 适用与不适用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>适用</th><th>不适用（需另议）</th></tr></thead><tbody><tr><td>单仓 Nest + 多 Agent</td><td>浏览器直连模型</td></tr><tr><td>别名数量可控（个位数到几十）</td><td>运行时每个用户自定义任意 upstream（变成代理产品）</td></tr><tr><td>与 LangChain ChatModel 对齐</td><td>非 Runnable 的异构推理服务无适配计划</td></tr></tbody></table><h3 id="_6-5-实现与策略外链-避免重抄" tabindex="-1">6.5 实现与策略外链（避免重抄） <a class="header-anchor" href="#_6-5-实现与策略外链-避免重抄" aria-label="Permalink to &quot;6.5 实现与策略外链（避免重抄）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主题</th><th>去哪读</th></tr></thead><tbody><tr><td><code>ModelGateway</code> / Registry 代码</td><td><a href="/ts-ai/backend/ai-service/model-gateway">backend · Model Gateway</a></td></tr><tr><td><code>withFallbacks</code>、主备、成本</td><td><a href="/ts-ai/agent/models-output/model-routing-fallbacks">模型路由与回退</a></td></tr><tr><td>请求级租户 Context</td><td><a href="/ts-ai/backend/ai-service/request-context-tenancy">请求 Context 与租户</a></td></tr></tbody></table><p>本 ADR 批准「要有 Gateway」；<strong>不</strong>批准某一版 npm API 细节——以实现文与官方 SDK 为准。</p><h3 id="_6-6-别名治理约定" tabindex="-1">6.6 别名治理约定 <a class="header-anchor" href="#_6-6-别名治理约定" aria-label="Permalink to &quot;6.6 别名治理约定&quot;">​</a></h3><table tabindex="0"><thead><tr><th>约定</th><th>说明</th></tr></thead><tbody><tr><td>命名</td><td><code>{domain}-{capability}</code>，如 <code>support-fast</code>、<code>kb-embed</code></td></tr><tr><td>稳定性</td><td>别名进入 contracts 后视为公开；重命名走弃用期</td></tr><tr><td>清单</td><td>README 或配置表列出别名、用途、默认 model、是否含 fallbacks</td></tr><tr><td>禁止</td><td>业务代码硬编码供应商 model 字符串绕过别名</td></tr><tr><td>测试</td><td>每个别名至少有 Fake 或录制契约，保证 <code>resolve</code> 不返回 <code>undefined</code></td></tr></tbody></table><p>售后最小集：<code>support-fast</code>、<code>support-reasoning</code>（可选 <code>support-resilient</code>）。<br> 知识库追加：<code>kb-embed</code>、<code>kb-chat</code>（可与 support 共用 chat 别名，但要在清单写明）。</p><h3 id="_6-7-与-run-trace-的关联" tabindex="-1">6.7 与 Run / Trace 的关联 <a class="header-anchor" href="#_6-7-与-run-trace-的关联" aria-label="Permalink to &quot;6.7 与 Run / Trace 的关联&quot;">​</a></h3><p>每次 <code>resolve</code> 用于某 Run 时，应用层应把 <code>alias</code>（及最终供应商/model 若可得）写入：</p><ul><li>Run metadata 或 Trace attributes</li><li>失败错误体（便于区分「别名不存在」与「上游 429」）</li></ul><p>没有关联，故障隔离与成本复盘都无法按别名切片。</p><h2 id="_7-复查条件" tabindex="-1">7. 复查条件 <a class="header-anchor" href="#_7-复查条件" aria-label="Permalink to &quot;7. 复查条件&quot;">​</a></h2><p>出现任一情况，重新打开本决策：</p><ol><li>模型调用量或延迟迫使独立扩缩 → 评估候选 C。</li><li>必须多区域多供应商智能路由且别名爆炸 → 评估专用路由服务，仍可保留薄 Gateway。</li><li>合规要求密钥与业务计算完全进程隔离 → 评估 C 或硬件隔离方案。</li><li>团队改为以托管 Agent 平台为唯一运行时 → 重评 D，并写退出策略。</li><li>发现业务代码再次直接 <code>new ChatOpenAI</code> 超过约定例外 → 视为回归，修边界而非默许。</li></ol><h2 id="_8-adr-记录-填写示例" tabindex="-1">8. ADR 记录（填写示例） <a class="header-anchor" href="#_8-adr-记录-填写示例" aria-label="Permalink to &quot;8. ADR 记录（填写示例）&quot;">​</a></h2><p>以下为售后工作台已填写示例，可直接贴进团队 ADR 库：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标题：采用 Nest 内 Model Gateway 作为模型交付面</span></span>
<span class="line"><span>状态：Accepted</span></span>
<span class="line"><span>日期：2026-08-07</span></span>
<span class="line"><span>场景：售后执行 Agent + 可选知识库检索</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问题：</span></span>
<span class="line"><span>  多处构造 ChatModel 导致密钥与超时不一致，供应商切换成本高。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>硬约束：</span></span>
<span class="line"><span>  Key 不出 Nest；LangChain.js；自托管；要 Trace 关联 alias。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>候选：</span></span>
<span class="line"><span>  A 直接构造 / B 应用内 Gateway / C 模型微服务 / D 纯托管入口</span></span>
<span class="line"><span></span></span>
<span class="line"><span>决策：</span></span>
<span class="line"><span>  选 B。别名 support-fast、support-reasoning、kb-embed。</span></span>
<span class="line"><span>  内容路由与 withFallbacks 策略见 agent 路由文；实现见 backend 网关文。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>后果：</span></span>
<span class="line"><span>  + 密钥轮换单点；Agent 测试可注入 Fake。</span></span>
<span class="line"><span>  − 需治理别名清单；禁止业务旁路构造。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>缓解：</span></span>
<span class="line"><span>  lint/codeowner 拦截直接 @langchain/openai 于 use-case 目录；</span></span>
<span class="line"><span>  启动校验必需要别名。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>复查：</span></span>
<span class="line"><span>  调用量 10× 或合规强制进程隔离时重评 C。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br></div></div><h3 id="_8-1-知识库变体-adr-片段" tabindex="-1">8.1 知识库变体 ADR 片段 <a class="header-anchor" href="#_8-1-知识库变体-adr-片段" aria-label="Permalink to &quot;8.1 知识库变体 ADR 片段&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>标题：知识库检索复用 Nest Model Gateway，并新增 kb-embed 别名</span></span>
<span class="line"><span>状态：Accepted</span></span>
<span class="line"><span>关联：售后 Gateway ADR（本文件主记录）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>增量决策：</span></span>
<span class="line"><span>  - 新增 alias kb-embed → Embedding 模型交付</span></span>
<span class="line"><span>  - kb-chat 可映射 support-fast 或独立配置</span></span>
<span class="line"><span>  - Embedding 失败不自动 fallback 到 Chat 别名（类型不兼容）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>否决：</span></span>
<span class="line"><span>  - 在 Nuxt 上传组件内直接调用 Embedding HTTP</span></span>
<span class="line"><span>  - 为每个租户动态注册无限别名（改为配置中心 + 审核）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="_9-常见误区与验收" tabindex="-1">9. 常见误区与验收 <a class="header-anchor" href="#_9-常见误区与验收" aria-label="Permalink to &quot;9. 常见误区与验收&quot;">​</a></h2><h3 id="_9-1-常见误区" tabindex="-1">9.1 常见误区 <a class="header-anchor" href="#_9-1-常见误区" aria-label="Permalink to &quot;9.1 常见误区&quot;">​</a></h3><ol><li><strong>把 Gateway 写成万能 AI 中台</strong>：鉴权、Prompt CMS、Agent 编排不属于网关。</li><li><strong>在 Gateway 里 <code>if (message.includes(&#39;退款&#39;))</code></strong>：那是路由策略，应可测、可观测地放在明确层。</li><li><strong>别名等于 model id</strong>：别名应稳定，model id 应可配。</li><li><strong>有了 fallbacks 就不设超时</strong>：超时与回退同时需要。</li><li><strong>前端也「resolve 一下」</strong>：违反密钥硬约束。</li><li><strong>Registry 与业务 Module 循环依赖</strong>：Gateway 应落在 infra，被 ai module 注入，而不是反过来依赖某个售后 UseCase。</li></ol><h3 id="_9-2-决策验收清单" tabindex="-1">9.2 决策验收清单 <a class="header-anchor" href="#_9-2-决策验收清单" aria-label="Permalink to &quot;9.2 决策验收清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>通过标准</th></tr></thead><tbody><tr><td>单点构造</td><td>业务目录无直接 <code>new ChatOpenAI</code>（测试 Fake 除外）</td></tr><tr><td>别名文档</td><td>清单与用途齐备</td></tr><tr><td>故障演练</td><td>拔掉主 upstream，观察 Run 失败或 fallback，且其它别名仍可 resolve</td></tr><tr><td>轮换演练</td><td>只改配置完成 Key/model 轮换</td></tr><tr><td>链路</td><td>Trace/Run 能看见 alias</td></tr></tbody></table><p>网关是基础设施上的窄门：让模型变得可交付、可替换、可隔离；让业务与 Agent 保持干净。</p>`,76)])])}const u=t(d,[["render",l]]);export{b as __pageData,u as default};
